if (root == nullptr || child == nullptr) return nullptr;

std::vector<Node*> stack;
stack.push_back(root);

while (!stack.empty()) {
    Node* current = stack.back();
    stack.pop_back();

    for (std::vector<Node*>::iterator it = current->children.begin(); it != current->children.end(); ++it) {
        if (*it == child) {
            return current;
        }
        stack.push_back(*it);
    }
}
return nullptr;
// END_CODE

